    if getattr(args, "old") is not None:
        kwargs["old"] = float(getattr(args, "old"))
    if getattr(args, "new") is not None:
        kwargs["new"] = float(getattr(args, "new"))

    from percent_change_skill import skill as _entry  # noqa
    result = _entry(_Ctx(), **kwargs)
    print(json.dumps(result, indent=2, ensure_ascii=False, default=str))


